'use strict';

var escape = require('../helpers/escape');

function _render(context, options) {

	var $ = context.jQuery,
		PubSub = context.PubSub;

	//Detect if the component has a diferent aligment
	var aligment = options.aligment === 'justified' ? 'btn-block' : '',
		name = options.name ? options.name : 'next',
		attrib = escape.htmlAttributeEscape(JSON.stringify(options), { singleQuotes: true });

	//HTML
	var $html = $(
		'<div class="form-group">' +
			'<button type="button" name="' + name + '" class="btn btn-success ' + aligment + ' f3-next" data-options=\'' + attrib + '\'>' +
				options.text +
			' <span class="glyphicon glyphicon-chevron-right"></span>' +
			'</button>' +
		'</div>'
	);

	//Bind
	$html.find('button').on('click', function (e) {

		//Prevent submit
		e.preventDefault();

		var $this = $(this),
			options = $(this).data('options'),
			$branch = $this.parents('.f3-branch'),
			validator = $branch.validate(context.settings.validate);

		//trigger validation for current branch
		if (validator.form()) {

			//Publish the event
			PubSub.publish('f3.next', {
				'trigger': this,
				'branch': options.branch,
				'event': 'go'
			});
		}

	});

	return $html;

}

function _read() {

	return null;

}

module.exports = {
	render: _render,
	read: _read,
	name: 'next'
};
